	// Rest API for pool management
	ahh.mux.HandleFunc(fmt.Sprintf("GET %s/pool", config.Cfg.APIBaseURL), func(w http.ResponseWriter, r *http.Request) { wrapperHandler(w, r, sbHeader.ListPool) })
	ahh.mux.HandleFunc(fmt.Sprintf("GET %s/pool/sandbox/{name}", config.Cfg.APIBaseURL), func(w http.ResponseWriter, r *http.Request) { wrapperHandler(w, r, sbHeader.ListPoolSandbox) })
	ahh.mux.HandleFunc(fmt.Sprintf("DELETE %s/pool/{name}", config.Cfg.APIBaseURL), func(w http.ResponseWriter, r *http.Request) { wrapperHandler(w, r, sbHeader.DeletePoolSandboxes) })

	// SandboxHandler router, route calls to Sandbox container(proxy)
	srHandler := router.NewSandboxRouter(ahh.rootCtx, a)
	ahh.mux.HandleFunc("/sandbox/{name}/", srHandler.ServeHTTP)

	// e2b API
	e2bHeader := e2bapi.NewHandler(ahh.rootCtx, c, a, srHandler)
	e2bHeader.RegisterHandlersWithOptions(ahh.mux)

	ahh.mux.Handle("/mcp", sbHeader.McpSseHandler())

	ahh.mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
		// return the json of status and version
		w.Header().Set("Content-Type", "application/json")
		fmt.Fprintf(w, `{"status":"ok","version":"%s"}`, config.Version)
		return
	})

	// ui router for static files
	uiDistFS := http.FileServer(http.Dir("ui/dist"))
	ahh.mux.Handle("/ui/", http.StripPrefix("/ui/", http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		uiDistFS.ServeHTTP(w, r)
	})))
	// Redirect the bare "/ui" to "/ui/" via a relative Location header (not an
	// absolute "/ui/"). Note: http.Redirect can't be used here — it rewrites a
	// relative target into an absolute path using r.URL.Path, which is already
	// prefix-stripped by any reverse proxy in front of this server, defeating the
	// purpose. Setting the header directly keeps it truly relative, so the browser
	// resolves it against the original request URL and any stripped proxy prefix
	// (e.g. "/agent-sandbox/ui" -> "/ui" as seen here) is preserved.
	ahh.mux.HandleFunc("/ui", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Location", "ui/")
		w.WriteHeader(http.StatusMovedPermanently)
	})

	// e2b data-plane sandbox access endpoint
	ahh.mux.HandleFunc("/sandboxes/router/{sandboxID}/{port}/", e2bHeader.SandboxRouterOfPath())
	// catch-all handler for any unmatched requests, mainly for E2B sandbox proxy by host ({port}-{sandbox_id}.{domain})
	ahh.mux.HandleFunc("/", e2bHeader.SandboxRouterOfDomain())
}

func wrapperHandler(w http.ResponseWriter, r *http.Request, f func(*http.Request) (interface{}, error)) {
	result, err := f(r)
	if err != nil {
		if httpErr, ok := err.(*HTTPError); ok {
			ErrWithCode(w, httpErr.Code, httpErr.Message)
			return
		}
		Err(w, err.Error())
		return
	}
	Ok(w, result)
	return
}

import { Navigate, Outlet, createHashRouter } from 'react-router-dom'

import AppShellLayout from '../layouts/AppShellLayout'
import { hasAuthToken } from '../lib/auth/token'
import DashboardPage from '../pages/DashboardPage'
import EventsPage from '../pages/EventsPage'
import FilesPage from '../pages/FilesPage'
import LoginPage from '../pages/LoginPage'
import LogsPage from '../pages/LogsPage'
import ControllerLogsPage from '../pages/ControllerLogsPage'
import MetricsPage from '../pages/MetricsPage'
import PoolDetailPage from '../pages/PoolDetailPage'
import PoolListPage from '../pages/PoolListPage'
import RateLimitPage from '../pages/RateLimitPage'
import RuntimeConfigPage from '../pages/RuntimeConfigPage'
import SandboxesPage from '../pages/SandboxesPage'
import SandboxBlueprintConfigPage from '../pages/SandboxBlueprintConfigPage'
import TemplatesConfigPage from '../pages/TemplatesConfigPage'
import TerminalPage from '../pages/TerminalPage'

function RequireAuth() {
  if (!hasAuthToken()) {
    return <Navigate to="/login" replace />
  }
  return <Outlet />
}

function RedirectIfAuthed() {
  if (hasAuthToken()) {
    return <Navigate to="/dashboard" replace />
  }
  return <LoginPage />
}

export const appRouter = createHashRouter([
  {
    path: '/login',
    element: <RedirectIfAuthed />,
  },
  {
    element: <RequireAuth />,
    children: [
      {
        path: '/',
        element: <AppShellLayout />,
        children: [
          {
            index: true,
            element: <Navigate to="dashboard" replace />,
          },
          {
            path: 'dashboard',
            element: <DashboardPage />,
          },
          {
            path: 'sandboxes',
            element: <SandboxesPage />,
          },
          {
            path: 'pool',
            element: <PoolListPage />,
          },
          {
            path: 'ratelimit',
            element: <RateLimitPage />,
          },
          {
            path: 'metrics',
            element: <MetricsPage />,
          },
          {
            path: 'controller-logs',
            element: <ControllerLogsPage />,
          },
          {
            path: 'logs',
            element: <LogsPage />,
          },
          {
            path: 'terminal',
            element: <TerminalPage />,
          },
          {
            path: 'files',
            element: <FilesPage />,
          },
          {
            path: 'events',
            element: <EventsPage />,
          },
          {
            path: 'pool/:poolName',
            element: <PoolDetailPage />,
          },
          {
            path: 'config/templates',
            element: <TemplatesConfigPage />,
          },
          {
            path: 'config/blueprint',
            element: <SandboxBlueprintConfigPage />,
          },
          {
            path: 'config/runtime',
            element: <RuntimeConfigPage />,
          },
        ],
      },
    ],
  },
  {
    path: '*',
    element: <Navigate to="/dashboard" replace />,
  },
])

const TOKEN_STORAGE_KEY = 'api-token'

export type NavKey =
  | 'dashboard'
  | 'sandboxes'
  | 'pool'
  | 'rateLimit'
  | 'metrics'
  | 'controllerLogs'
  | 'logs'
  | 'terminal'
  | 'files'
  | 'templatesConfig'
  | 'sandboxBlueprintConfig'
  | 'runtimeConfig'
  | 'events'

const DEFAULT_ALLOWED_NAVS: NavKey[] = ['dashboard', 'sandboxes', 'pool', 'rateLimit', 'metrics', 'controllerLogs', 'logs', 'terminal', 'files', 'events']

export function canAccessNav(key: NavKey, token = [REDACTED] boolean {
  if (token.startsWith('sys-')) {
    return true
  }

  return DEFAULT_ALLOWED_NAVS.includes(key)
}

export function getAuthToken(): string {
  try {
    return (localStorage.getItem(TOKEN_STORAGE_KEY) || '').trim()
  } catch {
    return ''
  }
}

export function setAuthToken(token: string): void {
  localStorage.setItem(TOKEN_STORAGE_KEY, token.trim())
}

export function clearAuthToken(): void {
  localStorage.removeItem(TOKEN_STORAGE_KEY)
}

export function hasAuthToken(): boolean {
  return getAuthToken() !== ''
}

